    const pic = res === "loss" || res === "again" ? "↻" : stale ? "😮" : res === "slow" ? "🐢" : "🤝";
    setTimeout(() => { if (eg !== my) return; $("eDone").innerHTML = `<div class="burst">${pic}</div>`; $("eDone").hidden = false; }, t);
    setTimeout(() => { if (eg === my) egStart(my.st); }, t + 2100);
