  if (kind === "r") s.push(`<path d="M-8,14 L-7,-6 H7 L8,14Z" fill="${col}" ${A_OUT}/><path d="M-10,-6 V-16 H-6 V-12 H-2 V-16 H2 V-12 H6 V-16 H10 V-6Z" fill="${col}" ${A_OUT} stroke-linejoin="round"/>`);
