  const glove = (x, y, r = 5.5, c = "#fff") => aC(x, y, r, c, st(1.2)) + line(`M${x - r * .5},${y - r * .2} h${r1(r)}`, .6);
  // quills from a list of points; triplets [base, tip, base] make the spikes (Shadow's stripes follow them)
