    const t = [hogBody(o), aC(33, 120, 2, "#2fd5e8"), a.armR ? "" : aC(87, 120, 2, "#2fd5e8"), hogHead(o)];
    if (a.armR) return [bg, aWrap(a.shadow, shadow(60, 148, 28), "60px 148px") + aWrap(a.hover, aEdge(t.join("")))];
    return [bg, aEdge(t.join(""))];
