      `<path d="M-9,-6 Q-7,-2 0,-2 Q7,-2 9,-6 Q8,-10 0,-9 Q-8,-10 -9,-6Z" fill="${D}" opacity=".5"/>` +
      eyes(-4.5, 4.5, -10, "#3a250f", .85) + blush(-8, -6, 1.6) + blush(8, -6, 1.6) + smile(0, -5, 2.2);
