    for (let i = 0; i < 5; i++) t.push(R(-40 + i * 15, -19, 11, 15, "#9fd4ef", 1.1, 'rx="1.5"') + line(`M${-38 + i * 15},-9 L${-32 + i * 15},-17`, 1.2, "#fff", 'opacity=".8"'));
    t.push(R(36, -19, 7, 15, "#9fd4ef", 1.1, 'rx="1.5"'));
