    t.push(tbW("bell", P("M50,104 Q50,96 60,96 Q70,96 70,104 L74,118 Q60,122 46,118Z", "#f2b51e", 1.4) + aC(60, 120, 3, "#9a6a10", st(1)) +
      R(57, 92, 6, 5, "#c9901a", 1) + hl("M54,104 Q54,99 58,98", 2, .7)));
