    t.push(aEye(48, 60, "#5a3a1a", .8, 1) + aEye(72, 60, "#5a3a1a", .8, 1));
    t.push(En(39, 69, 3.4, 2, "#ff7a8a", 'opacity=".6"') + En(81, 69, 3.4, 2, "#ff7a8a", 'opacity=".6"'));
