    return (i % 2 === 0 ? `<span class="n">${i / 2 + 1}.</span> ` : "") +
      `<span class="m nav${mine ? " me" : ""}${i === cur ? " last" : ""}" data-k="${i}">${esc(m.san)}${gaShown(fl) ? `<span class="gam ga-${GA_CLS[fl.cls]}">${GA_MARK[fl.cls]}</span>` : ""}</span>`;
